$site='https://racedaycompare.company';$root=Join-Path $PSScriptRoot '..\app\guides';New-Item -ItemType Directory -Force -Path $root|Out-Null
$guides=@(
@('flat-half-marathons','Flat half marathons in the current UK catalogue','Reviewed sources do not publish a confirmed ascent for these road half marathons. Unknown elevation is kept visible; this is not a claim that every course is flat.',@('richmond-park-half-marathon','alloa-half-marathon','inverness-half-marathon','cardiff-half-marathon')),
@('first-half-marathons','Half marathons for a first-time runner','A starting point for runners choosing a first half marathon. Check the current date, facilities and cut-off with the organiser before entering.',@('richmond-park-half-marathon','inverness-half-marathon','alloa-half-marathon','newport-marathon')),
@('trail-ultras-with-cutoffs','UK trail ultras with published cut-offs','Trail ultras where a cut-off or staged cut-offs were visible in the reviewed official source. Course and checkpoint rules still need careful reading.',@('south-downs-way-50','race-to-the-stones','snowdonia-trail-ultra-eryri','beacons-way-ultra-100')),
@('races-with-travel-information','Races with useful travel information','Events where the reviewed source provides some transport, coach, rail or shuttle information. This does not prove race-day timing feasibility.',@('great-north-run','alloa-half-marathon','loch-ness-marathon','richmond-park-half-marathon')),
@('welsh-trail-races','Welsh trail races and ultras','A source-linked Welsh trail shortlist across different distances and levels of commitment.',@('snowdonia-trail-ultra-eryri','beacons-way-ultra-100')),
@('northern-ireland-races','Northern Ireland races in the catalogue','Current Northern Ireland coverage is deliberately small. These pages show what is confirmed and where organiser verification is still needed.',@('norn-iron-100-half','omagh-half-marathon'))
