$s=@('<?xml version="1.0" encoding="UTF-8"?>','<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">');foreach($g in $guides){$slug=$g[0];$title=$g[1];$intro=$g[2];$links=($g[3]|ForEach-Object{"<li><a href='$site/races/$_/'>$_</a></li>"}) -join '';New-Item -ItemType Directory -Force -Path (Join-Path $root $slug)|Out-Null;$html=@("<!doctype html><html lang='en-GB'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>$title | Race Fieldnotes</title><meta name='description' content='$intro'><link rel='canonical' href='$site/guides/$slug/'><style>body{font:16px/1.6 system-ui;max-width:780px;margin:0 auto;padding:40px 22px;color:#13231f;background:#f5f3ed}a{color:#df6845}h1{font-size:clamp(2.5rem,7vw,5rem);line-height:.95}.note{border-left:3px solid #df6845;padding-left:14px;color:#68736d}</style></head><body>","<p><a href='$site/'>← Race Fieldnotes</a></p><p>DECISION GUIDE · UK RACES</p><h1>$title</h1><p>$intro</p><p class='note'>This guide uses the current Race Fieldnotes catalogue. Missing information remains unknown. Always check the organiser's current instructions.</p><h2>Current shortlist</h2><ul>$links</ul><h2>How to use this guide</h2><p>Compare the linked profiles for date, distance, surface, cut-off, travel and facilities. A missing field is not a positive or negative claim.</p></body></html>") -join "`n";Set-Content -Path (Join-Path (Join-Path $root $slug) 'index.html') -Value $html -Encoding utf8;$s+="<url><loc>$site/guides/$slug/</loc><priority>0.6</priority></url>"};$s+='</urlset>';Set-Content -Path (Join-Path $PSScriptRoot '..\app\guides-sitemap.xml') -Value ($s -join "`n") -Encoding utf8
